export function palindromePairs(words: string[]): number[][] {
  const out: number[][] = [];
  for (let i = 0; i < words.length; i++) for (let j = 0; j < words.length; j++) {
    if (i === j) continue;
    const text = words[i] + words[j]; let l = 0, r = text.length - 1;
    while (l < r && text[l] === text[r]) { l++; r--; }
    if (l >= r) out.push([i, j]);
  }
  return out;
}

