class FileSystem:
    def __init__(self):
        self.root = Node()
    def _walk(self, path):
        node = self.root
        for part in filter(None, path.split('/')):
            node = node.children.setdefault(part, Node())
        return node
    def ls(self, path):
        node = self._walk(path)
        if node.content is not None:
            return [path.split('/')[-1]]
        return sorted(node.children)
    def mkdir(self, path):
        self._walk(path)
