typescript.code:
class MinHeap<T> {
  private items: T[] = [];
  constructor(private compare: (a: T, b: T) => number) {}
  get size(): number { return this.items.length; }
  peek(): T | undefined { return this.items[0]; }
  push(value: T): void {
    const a = this.items; a.push(value);
    let i = a.length - 1;
    while (i > 0) { const p = Math.floor((i - 1) / 2); if (this.compare(a[p], a[i]) <= 0) break; [a[p], a[i]] = [a[i], a[p]]; i = p; }
  }
  pop(): T | undefined {
    const a = this.items;
    if (!a.length) return undefined;
    const first = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last; let i = 0;
      while (2 * i + 1 < a.length) {
        let child = 2 * i + 1;
        if (child + 1 < a.length && this.compare(a[child + 1], a[child]) < 0) child++;
        if (this.compare(a[i], a[child]) <= 0) break;
        [a[i], a[child]] = [a[child], a[i]]; i = child;
      }
    }
    return first;
  }
}
export function topKFrequent(nums: number[], k: number): number[] {
  const counts = new Map<number, number>();
  for (const value of nums) counts.set(value, (counts.get(value) ?? 0) + 1);
  const h = new MinHeap<[number, number]>((a, b) => a[0] - b[0]);
  for (const [value, count] of counts) { h.push([count, value]); if (h.size > k) h.pop(); }
  const out: number[] = []; while (h.size) out.push(h.pop()![1]); return out;
}

