export function isValid(s: string): boolean {
  const pairs = new Map<string, string>([[')', '('], [']', '['], ['}', '{']]);
  const stack: string[] = [];
  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') stack.push(ch);
    else if (pairs.has(ch) && stack.pop() !== pairs.get(ch)) return false;
  }
  return stack.length === 0;
}

