import { useState } from "react";
import { FileNode, toggleLocal } from "./model";
import { sample } from "./data";
import "./styles.css";
function FileItem({ node }: { node: FileNode }) {
  const [expanded, setExpanded] = useState(false);
  return (
    <li>
      {node.type === "file" ? (
        <span>{node.name}</span>
      ) : (
        <>
          <button
            aria-expanded={expanded}
            onClick={() => setExpanded((value) => toggleLocal(value, node))}
          >
            {expanded ? "▾" : "▸"} {node.name}
          </button>
          {expanded && (
            <ul>
              {node.children.length ? (
                node.children.map((child) => (
                  <FileItem key={child.id} node={child} />
                ))
              ) : (
                <li>Empty folder</li>
              )}
            </ul>
          )}
        </>
      )}
    </li>
  );
}
export function FileExplorer({ nodes }: { nodes: FileNode[] }) {
  return nodes.length ? (
    <ul className="tree">
      {nodes.map((node) => (
        <FileItem key={node.id} node={node} />
      ))}
    </ul>
  ) : (
    <p>No files</p>
  );
}
export default function App() {
  const [empty, setEmpty] = useState(false);
  return (
    <main>
      <h1>File explorer</h1>
      <p>
        Closing a parent unmounts children and resets their local expansion
        state.
      </p>
      <button onClick={() => setEmpty((value) => !value)}>
        Toggle empty data
      </button>
      <FileExplorer nodes={empty ? [] : sample} />
    </main>
  );
}

