  id,
  tree,
  expanded,
  onToggle,
}: {
  id: string;
  tree: NormalTree;
  expanded: ReadonlySet<string>;
  onToggle: (id: string) => void;
}) {
  const node = tree.nodes[id],
    open = expanded.has(id);
  return (
    <li>
      {node.type === "file" ? (
        <span>{node.name}</span>
      ) : (
        <>
          <button aria-expanded={open} onClick={() => onToggle(id)}>
            {open ? "▾" : "▸"} {node.name}
          </button>
          {open && (
            <ul>
              {node.children.length ? (
                node.children.map((child) => (
                  <FileItem
                    key={child}
                    id={child}
                    tree={tree}
                    expanded={expanded}
                    onToggle={onToggle}
                  />
                ))
              ) : (
                <li>Empty folder</li>
              )}
            </ul>
          )}
        </>
      )}
    </li>
  );
}
export function FileExplorer({ tree }: { tree: NormalTree }) {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
