from collections import defaultdict, deque

def vertical_order(root):
    if not root:
        return []
    cols = defaultdict(list)
    queue = deque([(root, 0)])
    while queue:
        node, col = queue.popleft()
        cols[col].append(node.val)
        if node.left:
            queue.append((node.left, col - 1))
        if node.right:
            queue.append((node.right, col + 1))
    return [cols[col] for col in sorted(cols)]

typescript.code:
type TreeNode = { val: number; left?: TreeNode | null; right?: TreeNode | null };
export function verticalOrder(root: TreeNode | null): number[][] {
  if (!root) return [];
  const cols = new Map<number, number[]>();
  const queue: Array<[TreeNode, number]> = [[root, 0]];
  for (let i = 0; i < queue.length; i += 1) {
    const [node, col] = queue[i];
    if (!cols.has(col)) cols.set(col, []);
    cols.get(col)!.push(node.val);
    if (node.left) queue.push([node.left, col - 1]);
    if (node.right) queue.push([node.right, col + 1]);
  }
  return [...cols.keys()].sort((a, b) => a - b).map((col) => cols.get(col)!);
}

