  const values = data.split(','); if (values[0] === '#') return null;
  const node = (v: string): TreeNode => ({val: Number(v), left: null, right: null});
  const root = node(values[0]), queue = [root]; let i = 1;
  for (let head = 0; head < queue.length; head++) {
    const parent = queue[head], left = values[i++], right = values[i++];
    if (left !== '#') { parent.left = node(left); queue.push(parent.left); }
    if (right !== '#') { parent.right = node(right); queue.push(parent.right); }
  }
  return root;
}

