class MinHeap<T> {
  private items: T[] = [];
  constructor(private compare: (a: T, b: T) => number) {}
  get size(): number { return this.items.length; }
  peek(): T | undefined { return this.items[0]; }
  push(value: T): void {
    const a = this.items; a.push(value);
    let i = a.length - 1;
    while (i > 0) { const p = Math.floor((i - 1) / 2); if (this.compare(a[p], a[i]) <= 0) break; [a[p], a[i]] = [a[i], a[p]]; i = p; }
  }
  pop(): T | undefined {
    const a = this.items;
    if (!a.length) return undefined;
    const first = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last; let i = 0;
      while (2 * i + 1 < a.length) {
        let child = 2 * i + 1;
        if (child + 1 < a.length && this.compare(a[child + 1], a[child]) < 0) child++;
        if (this.compare(a[i], a[child]) <= 0) break;
        [a[i], a[child]] = [a[child], a[i]]; i = child;
      }
    }
    return first;
  }
}

export class ExpiringCacheHeap<V> {
  private data = new Map<string, { value: V; expiresAt: number }>();
  private heap = new MinHeap<[number, string]>((a, b) => a[0] - b[0]);
  set(key: string, value: V, ttl: number, now: number): void {
    const expiresAt = now + ttl;
    this.data.set(key, { value, expiresAt });
    this.heap.push([expiresAt, key]);
  }
  cleanup(now: number): void {
    while (this.heap.size && this.heap.peek()![0] <= now) {
      const [expiresAt, key] = this.heap.pop()!;
      if (this.data.get(key)?.expiresAt === expiresAt) this.data.delete(key);
    }
  }
  get(key: string, now: number): V | undefined { this.cleanup(now); return this.data.get(key)?.value; }
}

